package com.hbm.client.missile.completion;
import com.hbm.client.bomb.nuclear.LegacyAbmContrailParticle;import com.hbm.client.missile.launchpad.rusted.LegacyLaunchSmokeParticle;import com.hbm.client.missile.launchpad.standard.*;import com.hbm.entity.missile.EntityMissileAntiBallistic;import com.hbm.missile.completion.MissileContent;import com.hbm.missile.launchpad.standard.*;import net.minecraft.client.Minecraft;import net.minecraft.client.multiplayer.ClientLevel;import net.minecraft.client.renderer.*;import net.minecraft.client.renderer.entity.NoopRenderer;import net.neoforged.api.distmarker.Dist;import net.neoforged.bus.api.SubscribeEvent;import net.neoforged.fml.common.EventBusSubscriber;import net.neoforged.neoforge.client.event.*;import net.neoforged.neoforge.client.extensions.common.IClientItemExtensions;import net.neoforged.neoforge.client.extensions.common.RegisterClientExtensionsEvent;
@EventBusSubscriber(modid="hbm",value=Dist.CLIENT,bus=EventBusSubscriber.Bus.MOD)
public final class MissileClient{
 @SubscribeEvent public static void renderers(EntityRenderersEvent.RegisterRenderers event){for(var kind:MissileContent.Kind.values())event.registerEntityRenderer(MissileContent.entity(kind).get(),context->new MissileRenderer(context,kind));event.registerEntityRenderer(MissileContent.EMP.get(),NoopRenderer::new);event.registerBlockEntityRenderer(StandardLaunchPadContent.ENTITY.get(),StandardLaunchPadRenderer::new);EntityMissileAntiBallistic.contrails=effect->{if(effect.level() instanceof ClientLevel level)Minecraft.getInstance().particleEngine.add(new LegacyAbmContrailParticle(level,effect.x(),effect.y(),effect.z()));};StandardLaunchPadBlockEntity.smoke=effect->{if(effect.level() instanceof ClientLevel level)Minecraft.getInstance().particleEngine.add(new LegacyLaunchSmokeParticle(level,effect.x(),effect.y(),effect.z(),effect.mx(),effect.my(),effect.mz()));};}
 @SubscribeEvent public static void screens(RegisterMenuScreensEvent event){event.register(StandardLaunchPadContent.MENU.get(),StandardLaunchPadScreen::new);}@SubscribeEvent public static void extensions(RegisterClientExtensionsEvent event){for(var kind:MissileContent.Kind.values())event.registerItem(new IClientItemExtensions(){private MissileItemRenderer renderer;@Override public BlockEntityWithoutLevelRenderer getCustomRenderer(){if(renderer==null)renderer=new MissileItemRenderer(kind);return renderer;}},MissileContent.missile(kind).get());event.registerItem(new IClientItemExtensions(){private StandardLaunchPadItemRenderer renderer;@Override public BlockEntityWithoutLevelRenderer getCustomRenderer(){if(renderer==null)renderer=new StandardLaunchPadItemRenderer();return renderer;}},StandardLaunchPadContent.ITEM.get());}private MissileClient(){}}
